interface.signature:
const authStore = useAuthStore()
// State:
authStore.user: { $id: string, name: string, email: string, ... } | null
authStore.userRoles: Array\u003c{ $id: string, name: string, permissions: string[] }\u003e
authStore.isLoggedIn: boolean
// Getters:
authStore.currentUser: User | null
authStore.isAuthenticated: boolean

const { hasPermission, hasAnyPermission, userStorageQuota } = usePermissions()
// Functions:
hasPermission(permission: string): boolean
hasAnyPermission(permissions: string[]): boolean
// Computed:
userStorageQuota.value: number (bytes, -1 for unlimited)

{
  path: 'profile',
  component: () => import('pages/profile/ProfilePage.vue'),
  meta: {
    requiresAuth: true  // Enforces authentication guard
  }
}
